// Folds the armed-guard (kill_enabled && !breaker_tripped) into this node: an
// unarmed breaker returns zero items, and every node downstream (Fetch insights /
// Load sample insights / everything after) naturally does nothing with zero input
// items -- no separate If node needed to short-circuit an unarmed run.
// actions_today enforcement (kill_enabled && !breaker_tripped && actions_today <
// max_actions_per_day) needs a persisted per-day counter this single manual-run
// demo does not query -- disclosed limitation, see README GOTCHAS.
const out = [];

for (const item of $input.all()) {
  const cfg = item.json;

  if (cfg.kill_enabled !== true) continue;
  if (cfg.breaker_tripped === true) continue;

  let timeRange = {};
  try {
    timeRange = JSON.parse(cfg.time_range_override || '{}');
  } catch (e) {
    timeRange = {};
  }

  const apiVer = String($env.META_API_VER || 'v22.0').trim();
  const adsetId = String(cfg.adset_id || '').trim();

  out.push({ json: {
    adset_id: adsetId,
    api_ver: apiVer,
    time_range: timeRange,
    fetch_url: 'https://graph.facebook.com/' + apiVer + '/' + adsetId + '/insights',
    daily_spend_cap_usd: Number(cfg.daily_spend_cap_usd || 0),
    cpl_cap_usd: Number(cfg.cpl_cap_usd || 0),
    min_spend_before_cpl_usd: Number(cfg.min_spend_before_cpl_usd || 0),
    zero_lead_spend_usd: Number(cfg.zero_lead_spend_usd || 0),
    cooldown_minutes: Number(cfg.cooldown_minutes || 0),
    max_actions_per_run: Number(cfg.max_actions_per_run || 1),
    dry_run: cfg.dry_run === true
  } });
}

return out;

// Masks BEFORE anything is stored, logged or rendered. Handles two shapes on the
// SAME input: the live Graph API insights response ({data:[...]}) and the disabled
// sample lane's file ({rows:[...]}, already masked at rest in samples/insights-sample.json).
// leads = MAX over action types matching /lead/i, NEVER the sum -- a row can carry
// both 'lead' and 'onsite_conversion.lead_grouped' for the SAME lead event.
// Folds the "Any rows?" throw-on-zero requirement into this node: zero normalized
// rows out is a hard stop, not a silent green (no alwaysOutputData anywhere in this
// workflow).
function maskTail(raw) {
  const s = String(raw == null ? '' : raw);
  const tail = s.length >= 4 ? s.slice(-4) : s;
  return '\u2022\u2022\u2022\u2022' + tail;
}

function leadsFromActions(actions) {
  if (!Array.isArray(actions)) return 0;
  let max = 0;
  for (const a of actions) {
    const t = String((a && a.action_type) || '');
    if (/lead/i.test(t)) {
      const v = Number((a && a.value) || 0);
      if (v > max) max = v;
    }
  }
  return max;
}

const ACCOUNT_REF_MASKED = 'act_\u2022\u2022\u2022\u20223502'; // our own ad account, masked -- never the raw id

let rawAdsetId = '';
try {
  rawAdsetId = String($('Build insights request').first().json.adset_id || '');
} catch (e) {
  rawAdsetId = '';
}

const out = [];

for (const item of $input.all()) {
  const j = item.json;

  if (Array.isArray(j.data)) {
    for (const row of j.data) {
      const spend = Number(row.spend || 0);
      const leads = leadsFromActions(row.actions);
      out.push({ json: {
        account_ref: ACCOUNT_REF_MASKED,
        adset_ref: maskTail(rawAdsetId),
        adset_name: 'HVAC AU 28-60 broad',
        spend: spend,
        impressions: Number(row.impressions || 0),
        clicks: Number(row.clicks || 0),
        ctr: Number(row.ctr || 0),
        date_start: row.date_start || null,
        date_stop: row.date_stop || null,
        leads: leads,
        cpl: leads > 0 ? spend / leads : null,
        source: 'live',
        adset_id_for_gate: rawAdsetId
      } });
    }
  } else if (Array.isArray(j.rows)) {
    for (const row of j.rows) {
      const spend = Number(row.spend || 0);
      const leads = leadsFromActions(row.actions);
      out.push({ json: {
        account_ref: row.account_ref || null,
        adset_ref: row.adset_ref || null,
        adset_name: row.adset_name || null,
        spend: spend,
        impressions: Number(row.impressions || 0),
        clicks: Number(row.clicks || 0),
        ctr: Number(row.ctr || 0),
        date_start: row.date_start || null,
        date_stop: row.date_stop || null,
        leads: leads,
        cpl: leads > 0 ? spend / leads : null,
        source: 'sample',
        lag_hours_since_last_impression: row.lag_hours_since_last_impression,
        adset_id_for_gate: null
      } });
    }
  }
}

if (out.length === 0) {
  throw new Error('Any rows?: zero insight rows after normalize -- refusing to evaluate the breaker on no data.');
}

return out;

// THE BRAIN. Reads every threshold from the caps row (Load caps / ep06_caps) --
// nothing is a magic number here. Reads the normalized insight fields by node
// reference (not $json) because this node sits downstream of Store snapshot's
// CTE, whose own $json is {id, actions_today} -- the Postgres result row, not the
// insight fields.
//
// Trip check placed HERE, not in Build insights request, mirroring the live
// estate's MA-02 "Evaluate Rules" node exactly: MA-02 checks consecutive_api_errors
// >= error_trip_threshold inside the SAME node that evaluates the pause rules, not
// in an upstream fetch-builder. consecutive_api_errors is maintained by the error
// workflow (Error Trigger -> Log error -> Read caps -> Bump error counter), which
// increments it on every Fetch insights / Pause at Meta / Verify effective status
// failure; Trip breaker resets nothing -- a tripped breaker never un-trips itself.
//
// Rule order: api-error trip -> min-data guard -> lag guard -> R3 (CPL) -> R1
// (spend cap) -> R2 (zero-lead) -> daily action cap (refuses a pause verdict, does
// not override a trip).
const norm = $("Mask + normalize").item.json;
let cfg = {};
try {
  cfg = $("Load caps").first().json || {};
} catch (e) {
  cfg = {};
}

const spend = Number(norm.spend || 0);
const leads = Number(norm.leads || 0);
const cpl = norm.cpl;
const minSpend = Number(cfg.min_spend_before_cpl_usd || 0);
const dailyCap = Number(cfg.daily_spend_cap_usd || 0);
const zeroLeadCap = Number(cfg.zero_lead_spend_usd || 0);
const cplCap = Number(cfg.cpl_cap_usd || 0);
const dryRun = cfg.dry_run === true;
const dateStop = String(norm.date_stop || "");
const adsetRefForKey = norm.adset_id_for_gate || norm.adset_ref || "unknown";

const consecutiveErrors = Number(cfg.consecutive_api_errors || 0);
const errorTripThreshold = Number(cfg.error_trip_threshold || 3);

const actionsToday = Number(($json && $json.actions_today) || 0);
const maxPerDay = Number(cfg.max_actions_per_day || 0);

let lagHours = null;
if (
  Object.prototype.hasOwnProperty.call(
    norm,
    "lag_hours_since_last_impression",
  ) &&
  norm.lag_hours_since_last_impression !== undefined &&
  norm.lag_hours_since_last_impression !== null
) {
  lagHours = Number(norm.lag_hours_since_last_impression);
}
const insideLagWindow = lagHours !== null && lagHours < 28;

function money(v) {
  return "$" + Number(v || 0).toFixed(2);
}

function base(kind, rule, reason) {
  return {
    json: {
      kind: kind,
      rule: rule,
      reason: reason,
      adset_ref: norm.adset_ref,
      adset_id_for_gate: norm.adset_id_for_gate,
      object_id: norm.adset_id_for_gate,
      object_name: norm.adset_name,
      observed: {
        spend: spend,
        leads: leads,
        cpl: cpl,
        cpl_cap_usd: cplCap,
        daily_spend_cap_usd: dailyCap,
        zero_lead_spend_usd: zeroLeadCap,
        min_spend_before_cpl_usd: minSpend,
        consecutive_api_errors: consecutiveErrors,
        error_trip_threshold: errorTripThreshold,
        actions_today: actionsToday,
        max_actions_per_day: maxPerDay,
      },
      idempotency_key: "ep06:" + adsetRefForKey + ":" + rule + ":" + dateStop,
      dry_run: dryRun,
    },
  };
}

// Daily action cap: refuses a would-be pause, never overrides a trip. A tripped
// breaker still needs to reach Trip breaker regardless of how many actions already
// fired today.
function enforceDailyCap(candidate) {
  if (candidate.json.kind === "pause" && actionsToday >= maxPerDay) {
    return base(
      "none",
      "daily-cap",
      "daily action cap reached (" +
        actionsToday +
        "/" +
        maxPerDay +
        ") -- refusing to pause",
    );
  }
  return candidate;
}

// 0. self-demotion on repeated API failure -- acting on stale data is worse than
// not acting. Checked first, ahead of every other rule.
if (consecutiveErrors >= errorTripThreshold) {
  return base(
    "trip",
    "api-error-trip",
    consecutiveErrors +
      " consecutive Graph API errors (threshold " +
      errorTripThreshold +
      "). Refusing to act on stale data.",
  );
}

if (spend < minSpend) {
  return base(
    "none",
    "min-data",
    "min-data guard: spend " +
      money(spend) +
      " < floor " +
      money(minSpend) +
      " -- unknown, not a breach",
  );
}

if (leads === 0 && insideLagWindow) {
  return base(
    "none",
    "lag",
    "lag guard: 0 leads but only " +
      lagHours +
      "h since last impression (settle window 28h) -- unknown, not a breach",
  );
}

if (leads >= 1 && cpl !== null && cpl > cplCap) {
  return enforceDailyCap(
    base(
      "pause",
      "R3",
      "R3 CPL breach: cpl = spend/leads = " +
        money(spend) +
        "/" +
        leads +
        " = " +
        money(cpl) +
        " > cap " +
        money(cplCap),
    ),
  );
}

if (spend >= dailyCap) {
  return enforceDailyCap(
    base(
      "pause",
      "R1",
      "R1 spend-cap breach: spend " +
        money(spend) +
        " >= cap " +
        money(dailyCap),
    ),
  );
}

if (leads === 0 && spend >= zeroLeadCap) {
  return enforceDailyCap(
    base(
      "pause",
      "R2",
      "R2 zero-lead breach: spend " +
        money(spend) +
        " >= zero-lead cap " +
        money(zeroLeadCap) +
        " with 0 leads",
    ),
  );
}

return base("none", "clean", "clean pass: all rules pass");

// ===================== WRITE WHITELIST GATE =====================
// Same chokepoint pattern as the estate's live breaker, MA-02 (1AmiT4eqfzIFH4TW):
// this node builds the write body ITSELF from constants -- callers never supply
// one -- so the only body that can physically reach Meta is {status:'PAUSED'}.
// There is no code path here that emits ACTIVE, budgets, bid, targeting or
// creative. It also refuses any object id that is not the allowlisted ad set
// from the ep06_caps Data Table row, so a corrupted or synthetic item (e.g. from
// the disabled sample lane, whose rows carry no raw id at all) can never reach a
// real Meta write. Throws, never skips -- same hard-fail shape as MA-02.
const ALLOWED_FIELD = 'status';
const ALLOWED_VALUE = 'PAUSED';

let cfg = {};
try {
  cfg = $('Load caps').first().json || {};
} catch (e) {
  cfg = {};
}
const allowlist = new Set([String(cfg.adset_id || '')].filter(Boolean));

const out = [];
for (const item of $input.all()) {
  const j = item.json;

  if (j.kind !== 'pause') {
    throw new Error('WRITE WHITELIST: refusing item of kind "' + j.kind + '". Only kind=pause may reach the Meta write path.');
  }

  const id = String(j.object_id || '').trim();
  if (!id) {
    throw new Error('WRITE WHITELIST: refusing a pause with an empty object_id.');
  }
  if (!allowlist.has(id)) {
    throw new Error('WRITE WHITELIST: object_id is not the allowlisted ad set from ep06_caps. Refusing to write to an unrecognised Meta object.');
  }

  const body = {};
  body[ALLOWED_FIELD] = ALLOWED_VALUE;
  const keys = Object.keys(body);
  if (keys.length !== 1 || keys[0] !== ALLOWED_FIELD || body[ALLOWED_FIELD] !== ALLOWED_VALUE) {
    throw new Error('WRITE WHITELIST: constructed body failed its own assertion: ' + JSON.stringify(body));
  }

  const apiVer = String($env.META_API_VER || 'v22.0').trim();
  out.push({ json: Object.assign({}, j, {
    request_body: body,
    write_url: 'https://graph.facebook.com/' + apiVer + '/' + id,
    verify_url: 'https://graph.facebook.com/' + apiVer + '/' + id + '?fields=id,configured_status,effective_status'
  }) });
}
return out;

// One summary item, read straight off the execution panel. Runs for every
// verdict branch (none / trip / pause) so a "nothing to do" run still reports.
function all(name) {
  try {
    return $(name).all().map(function (i) { return i.json; });
  } catch (e) {
    return [];
  }
}

const normalized = all('Mask + normalize');
const evaluated = all('Evaluate breaker');
const gated = all('WRITE WHITELIST GATE');
const receipts = all('Write receipt');
const tripped = all('Trip breaker');

const kinds = {};
for (const e of evaluated) {
  kinds[e.kind] = (kinds[e.kind] || 0) + 1;
}

const dryRunActive = evaluated.length ? evaluated[0].dry_run === true : null;

return [{ json: {
  rows_evaluated: normalized.length,
  none_count: kinds.none || 0,
  trip_count: kinds.trip || 0,
  pause_count: kinds.pause || 0,
  actions_gated: gated.length,
  receipts_written: receipts.length,
  breaker_trips_written: tripped.length,
  dry_run: dryRunActive,
  spend_observed: normalized.length ? normalized[0].spend : null,
  leads_observed: normalized.length ? normalized[0].leads : null,
  clicks_observed: normalized.length ? normalized[0].clicks : null,
  impressions_observed: normalized.length ? normalized[0].impressions : null
} }];
